*** tokio-util/tests/time_delay_queue.rs.orig
--- tokio-util/tests/time_delay_queue.rs
***************
*** 169,174 ****
--- 169,213 ----
      assert!(entry.is_none());
  }

+ #[tokio::test]
+ async fn remove_last_entry_wakes_poller() {
+     time::pause();
+ 
+     let mut queue = task::spawn(DelayQueue::new());
+     let key = queue.insert("foo", ms(100));
+     let other_key = queue.insert("bar", ms(200));
+ 
+     assert_pending!(poll!(queue));
+     assert!(!queue.is_woken());
+ 
+     let entry = queue.remove(&other_key);
+     assert_eq!(entry.into_inner(), "bar");
+     assert!(!queue.is_woken());
+ 
+     let entry = queue.remove(&key);
+     assert_eq!(entry.into_inner(), "foo");
+     assert!(queue.is_woken());
+     assert!(assert_ready!(poll!(queue)).is_none());
+ }
+ 
+ #[tokio::test]
+ async fn try_remove_last_entry_wakes_poller() {
+     time::pause();
+ 
+     let mut queue = task::spawn(DelayQueue::new());
+     let key = queue.insert("foo", ms(100));
+ 
+     assert_pending!(poll!(queue));
+     assert!(!queue.is_woken());
+ 
+     let entry = queue.try_remove(&key).unwrap();
+     assert_eq!(entry.into_inner(), "foo");
+     assert!(queue.is_woken());
+     assert!(assert_ready!(poll!(queue)).is_none());
+ 
+     assert!(queue.try_remove(&key).is_none());
+     assert!(!queue.is_woken());
+ }
+ 
  #[tokio::test]
  async fn reset_entry() {
      time::pause();
PATCH
cargo test -p tokio-util --features full --test time_delay_queue last_entry_wakes_poller

